async function readLocalManifest(directory) {
  try {
    return parseManifest(JSON.parse((await regularFile(await realpath(resolve(directory)), "telo.plugin.json", limits.manifest)).toString("utf8")));
  } catch (error) {
    if (error instanceof PluginError)
      throw error;
    throw new PluginError("plugin_manifest_invalid");
  }
}
async function loadLocalPackage(directory) {
  const root = await realpath(resolve(directory));
  const manifest = await readLocalManifest(root);
  const files = {};
  for (const path of [
    "telo.plugin.json",
    "package.json",
    "README.md",
    "LICENSE",
    manifest.runtime.entry,
    ...manifest.skills.map((s) => s.path)
  ])
    files[path] = await regularFile(root, path, path === manifest.runtime.entry ? limits.bundle : limits.manifest);
  for (const skill of manifest.skills) {
    const directory = posix3.dirname(skill.path);
    const queue = [skill.path];
    const visited = new Set;
    let total = 0;
    while (queue.length) {
      const path = queue.shift();
      if (!path || visited.has(path))
        continue;
      visited.add(path);
      if (visited.size > 33)
        throw new PluginError("plugin_package_invalid");
      files[path] ??= await regularFile(root, path, path === skill.path ? 16384 : 65536);
      total += files[path].length;
      if (total > 262144)
        throw new PluginError("plugin_package_invalid");
      for (const linked of skillResourcePaths(files[path].toString("utf8"), posix3.relative(directory, path)))
        queue.push(posix3.join(directory, linked));
    }
  }
  return { root, files, ...validatePackageFiles(files) };
}
function generatedContractPath(directory) {
  return join(resolve(directory), "src", "generated", "contract.ts");
}

// scripts/plugin-cli.ts
var [command, directory = ".", tool, inputFile, fixtureFile, unsafe] = process.argv.slice(2);
try {
  if (command === "schema") {
    process.stdout.write(`${JSON.stringify(toJSONSchema(manifestSchema, { target: "draft-2020-12" }), null, 2)}
`);
  } else if (command === "generate") {
    const manifest = await readLocalManifest(directory);
    const path = generatedContractPath(directory);
    await mkdir(dirname2(path), { recursive: true });
    await writeFile(path, generateContract(manifest));
    process.stdout.write(`Generated plugin types.
`);
  } else if (command === "build") {
    const manifest = await readLocalManifest(directory);
    const generated = generatedContractPath(directory);
    await mkdir(dirname2(generated), { recursive: true });
    await writeFile(generated, generateContract(manifest));
    const output = resolve2(directory, manifest.runtime.entry);
    const result = await Bun.build({
      entrypoints: [resolve2(directory, "src/index.ts")],
      root: resolve2(directory),
      target: "node",
      format: "esm",
      outdir: dirname2(output),
      naming: output.split("/").at(-1),
      plugins: [
        {
          name: "telo-preview-sdk",
          setup(build) {
            build.onResolve({ filter: /^@telo\/plugin-sdk$/ }, () => ({
              path: resolve2(dirname2(resolve2(process.argv[1] ?? "scripts/plugin-cli.ts")), "../sdk/plugin/index.ts")
            }));
          }
        }
      ]
    });
    if (!result.success)
      throw new PluginError("plugin_package_invalid");
    await loadLocalPackage(directory);
    process.stdout.write(`Built and validated Node ESM plugin.
`);
  } else if (command === "validate") {
    const pkg = await loadLocalPackage(directory);
    process.stdout.write(`${JSON.stringify({ id: pkg.manifest.id, version: pkg.manifest.version, digest: pkg.digest, tools: pkg.manifest.tools.map((t) => t.name) })}
`);
  } else if (command === "run") {
    if (!tool || !inputFile || !fixtureFile || unsafe !== "--unsafe-local")
      throw new PluginError("plugin_permission_denied");
    const pkg = await loadLocalPackage(directory);
    const fixtures = object({
      grants: array(_enum(["github.metadata.read", "http.read"])),
      responses: record(string2(), json()),
      settings: record(string2(), json()).optional()
    }).strict().parse(JSON.parse(await readFile2(fixtureFile, "utf8")));
    const input = validateInput(pkg.manifest, tool, JSON.parse(await readFile2(inputFile, "utf8")));
    const settings = validateSettings(pkg.manifest, fixtures.settings ?? {});
    const definition = validateDefinition(pkg.manifest, (await import(pathToFileURL(resolve2(directory, pkg.manifest.runtime.entry)).href)).default);
    const context = createToolContext({
      manifest: pkg.manifest,
      tool,
      settings,
      signal: AbortSignal.timeout(30000),
      invocation: {
        id: randomUUID(),
        deadline: new Date(Date.now() + 30000).toISOString()
      },
      grants: fixtures.grants,
      guard: async () => {},
      broker: async (request) => {
        const key = JSON.stringify(request);
        if (!Object.hasOwn(fixtures.responses, key))
          throw new PluginError("plugin_permission_denied");
        return fixtures.responses[key];
      }
    });
    const handler = definition.tools[tool];
    if (!handler)
      throw new PluginError("plugin_package_invalid");
    const result = validateResult(pkg.manifest, tool, await handler(input, context));
    process.stdout.write(`${JSON.stringify({ mode: "trusted-offline-harness-without-os-isolation", result })}
`);
  } else {
    process.stderr.write(`Usage: plugin-cli <schema|generate|build|validate> [directory]
       plugin-cli run <directory> <tool> <input.json> <fixtures.json> --unsafe-local
`);
    process.exitCode = 1;
  }
} catch (error) {
  process.stderr.write(`${error instanceof PluginError ? error.code : "plugin_package_invalid"}
`);
  process.exitCode = 1;
}
